/** Keeps the height of `el` current as a CSS variable on `on`, and returns its
 *  stop. A sticky band whose height is a constant in the stylesheet drifts.
 *  Sub-pixel exact: a rounded-up bar leaves a seam under it through which the
 *  list shows, a rounded-down one parks a jump target behind it. */
export function publishHeight(el: HTMLElement, name: string, on: HTMLElement): () => void {
  return publish(el, name, on, null);
}

/** The same, but for a bar that stands in several copies (one section head per
 *  section). The reader meets one of them at a time, so the room a scroll
 *  target needs is the one of the HIGHEST head — a count that wraps on a
 *  narrow screen makes one head higher than the next. */
export function publishHighest(el: HTMLElement, name: string, on: HTMLElement): () => void {
  let pool = pools.get(name);
  if (!pool) { pool = new Map(); pools.set(name, pool); }
  return publish(el, name, on, pool);
}

const pools = new Map<string, Map<Element, number>>();

function publish(
  el: HTMLElement, name: string, on: HTMLElement, pool: Map<Element, number> | null,
): () => void {
  if (typeof el.getBoundingClientRect !== 'function') return () => {};
  let previous = -1;
  const write = () => {
    if (!pool) { on.style.setProperty(name, `${previous}px`); return; }
    pool.set(el, previous);
    on.style.setProperty(name, `${Math.max(...pool.values())}px`);
  };
  const measure = () => {
    const h = el.getBoundingClientRect().height;
    if (h === previous) return;
    previous = h;
    write();
  };
  measure();
  const ro = typeof ResizeObserver === 'function' ? new ResizeObserver(measure) : null;
  ro?.observe(el);
  return () => {
    ro?.disconnect();
    if (!pool) return;
    pool.delete(el);
    on.style.setProperty(name, pool.size ? `${Math.max(...pool.values())}px` : '0px');
  };
}
