import { createEffect, lazy, on, onCleanup, onMount, Show, untrack } from 'solid-js';
import { VERSION } from './version.js';
import { sources, endpointIsSource, rebuild, loadCorpus } from './stores/corpus.js';
import { reveal, jump, text, view, setNotice } from './stores/view.js';
import { EditChrome, EditButton, sourcePanelEdited } from './ui/app/edit-mode.jsx';
import {
  openedByApp, setOpenedByApp, setSourcesOpen, sourcesOpen, SourcesButton, SourcesPanel,
} from './ui/app/sources.jsx';
import { Starter } from './ui/app/starter.jsx';
import { startSourceManagement } from './stores/source-management.js';
import { FillPanel, jumpToRef as jumpInPanel } from './ui/card/fill.jsx';
import { StatusLine } from './ui/app/status.jsx';
import { LanguagePicker } from './ui/app/language-picker.jsx';
import { Sections } from './ui/list/sections.jsx';
import { Sidenav } from './ui/sidenav/sidenav.jsx';
import { publishHeight } from './ui/shared/band.js';

const SparqlState = lazy(async () => ({
  default: (await import('./ui/sparql/sparql.jsx')).SparqlState,
}));

export async function jumpToRef(ref: string): Promise<void> {
  setNotice(null);
  const landed = await jump(ref, { smooth: true });

  if (!landed) setNotice('jump.notInDoc');
}

export function jumpFromPanel(ref: string, scope: string | null): void {
  reveal(ref);
  setTimeout(() => { jumpInPanel(ref, scope); }, 0);
}

startSourceManagement();

export function App() {

  onMount(() => {
    if (typeof document === 'undefined') return;
    const header = document.querySelector('.app-header') as HTMLElement | null;
    if (!header) return;
    onCleanup(publishHeight(header, '--header-h', document.documentElement));
  });

  // A panel the app opened itself closes again as soon as sources arrive, and
  // hands focus back rather than leaving it in a drawer that is gone.
  createEffect(() => {
    if (!sourcesOpen()) { setOpenedByApp(false); return; }
    if (!openedByApp() || !sources().length) return;
    setOpenedByApp(false);

    const panel = typeof document === 'undefined' ? null
      : document.getElementById('sources-drawer');
    const inside = !!(panel && document.activeElement && panel.contains(document.activeElement));
    setSourcesOpen(false);
    if (inside) (document.getElementById('app-main') as HTMLElement | null)?.focus();
  });

  createEffect(() => {
    document.documentElement.setAttribute('lang', view.lang);
  });

  createEffect(() => {
    const src = [...view.src];
    const ttl = [...view.ttl];
    const sparql = view.sparql ?? undefined;

    setNotice(null);
    // Untracked: a language switch must rebuild, not refetch the corpus.
    untrack(() => loadCorpus({
      src, ttl, sparql, policyScope: view.policyScope, setScope: view.setScope,
      lang: view.lang, excludeGraphs: view.excludeGraphs,
    }));
  });

  createEffect(on(() => view.lang, () => {
    setNotice(null);
    void rebuild({ lang: view.lang });
  }, { defer: true }));

  return (
    <>
            <a class="skip-link" href="#app-main">{text('tree.skip')}</a>
      <Sidenav onJump={jumpToRef} />
      <header class="app-header" id="app-header">
        <div class="app-brand">
          <span class="logo">ODRL Visualizer</span>
                    <span class="version" id="app-version">{VERSION}</span>
        </div>
                <div class="header-actions">
                    <EditButton />
          <SourcesButton />
          <LanguagePicker />
        </div>
      </header>
            <EditChrome />
            <SourcesPanel editing={sourcePanelEdited} />
      <main class="app-main" id="app-main" tabindex="-1">
        <Starter />
                <Show when={view.sparql || endpointIsSource()} fallback={<Sections />}>
          <SparqlState><Sections /></SparqlState>
        </Show>
      </main>
      <StatusLine />
            <FillPanel onJump={jumpFromPanel} />
    </>
  );
}
