import { createMemo, createSignal, onCleanup, onMount, Show } from 'solid-js';
import type { Accessor, JSX } from 'solid-js';
import { lifecyclePluralWord } from '../../model/parse.js';
import { num } from '../../model/i18n.js';
import { listPhase } from '../../stores/corpus.js';
import { LIFECYCLES, text, view, setView } from '../../stores/view.js';
import type { Lifecycle } from '../../stores/view.js';
import { GroupingPath, groupingDiffers, restoreGrouping, closeDimMenu } from './pivot.jsx';
import { publishHighest } from '../shared/band.js';
import './list.css';

export interface OfferOption { iri: string; title: string }

export interface SectionFilterOptions {

  id: string;

  withStatus?: boolean;

  offers?: () => OfferOption[];

  ariaLabel?: string;
}

export interface SectionFilter {
  id: string;
  withStatus: boolean;
  offerOptions: Accessor<OfferOption[]>;

  text: Accessor<string>;
  setText: (v: string) => void;

  offerIri: Accessor<string>;
  setOffer: (iri: string) => void;

  state: Accessor<string>;

  status: Accessor<Lifecycle[] | null>;
  setStatus: (v: Lifecycle[] | null) => void;

  passes: (status: string | null | undefined) => boolean;

  active: Accessor<boolean>;

  suffix: Accessor<string>;

  countText: Accessor<string>;

  /** How many cards actually stand in the section right now. */
  visible: Accessor<number>;

  setCount: (visible: number, total: number) => void;

  clear: () => void;
  open: Accessor<boolean>;
  setOpen: (v: boolean) => void;

  loading: Accessor<boolean>;
}

export function makeSectionFilter(options: SectionFilterOptions): SectionFilter {
  const [searchText, setSearchText] = createSignal('');
  const [open, setOpen] = createSignal(false);
  const [visible, setVisible] = createSignal(0);
  const [total, setTotal] = createSignal(0);
  const withStatus = options.withStatus !== false;
  const offerOptions = () => (options.offers ? options.offers() : []);
  const withOffers = () => offerOptions().length > 0;

  const status = () => (withStatus ? view.filters.status : null);

  const offerIri = () => {
    const want = withOffers() ? view.filters.offer : '';
    return offerOptions().some((o) => o.iri === want) ? want : '';
  };

  const setStatus = (v: Lifecycle[] | null) => {
    setView({ filters: { ...view.filters, status: v } });
  };
  const setOffer = (iri: string) => {
    setView({ filters: { ...view.filters, offer: iri } });
  };

  const active = createMemo(() => !!searchText() || !!status() || !!offerIri()
    || groupingDiffers());

  const suffix = () => {
    let out = '';
    const off = offerIri();
    if (off) {
      const o = offerOptions().find((x) => x.iri === off);
      out += text('filter.suffixOffer', { title: (o && o.title) || off });
    }
    const st = status();
    if (!st) return out;
    if (!st.length) return out + text('filter.suffixNoStatus');
    const words = LIFECYCLES.filter((s) => st.includes(s))
      .map((s) => lifecyclePluralWord(s) as string);
    return out + ' · ' + (words.length === 1
      ? text('filter.suffixOnly', { word: words[0] }) : words.join(' + '));
  };

  // Raw choices only. Reading the model here would make every model rebuild
  // look like a filter change to the card list.
  const state = createMemo(() => [
    searchText(),
    options.offers ? view.filters.offer : '',
    withStatus ? (view.filters.status || []).join(',') : '',
  ].join('\u0000'));

  const countText = () => {

    if (listPhase() === 'first') return '· …';
    const n = visible();
    const t = total();
    return '· ' + (n === t ? num(t) : text('count.ofTotal', { n, total: t })) + suffix();
  };

  return {
    id: options.id,
    withStatus,
    offerOptions,
    text: searchText,
    setText: setSearchText,
    offerIri,
    setOffer,
    state,
    status,
    setStatus,
    passes: (s) => {
      const st = status();
      return !st || st.includes((s || 'active') as Lifecycle);
    },
    active,
    suffix,
    countText,
    visible,
    setCount: (n, t) => { setVisible(n); setTotal(t); },
    clear: () => {
      setSearchText('');

      restoreGrouping();
      setView({ filters: { status: null, offer: withOffers() ? '' : view.filters.offer } });
    },
    open,
    setOpen,
    loading: () => listPhase() === 'first',
  };
}

export function FilterButton(props: { filter: SectionFilter }): JSX.Element {
  const f = () => props.filter;
  return (
    <button
      type="button"
      class={'sec-filter-btn' + (f().active() ? ' on' : '')}
      aria-expanded={f().open()}
      aria-haspopup="true"
      title={f().loading() ? text('filter.loading') : text('filter.title')}
      aria-label={text('filter.toggleAria')}
      onClick={(e) => { e.preventDefault(); e.stopPropagation(); f().setOpen(!f().open()); }}
      onPointerDown={(e) => e.stopPropagation()}
    >
            <svg viewBox="0 0 16 16" width="13" height="13" aria-hidden="true">
        <path d="M1.5 2.5h13L9.5 8.6v4.3l-3 1.6V8.6z" fill="currentColor" />
      </svg>
    </button>
  );
}

function Item(props: { label: string; children: JSX.Element }): JSX.Element {
  return (
    <div class="sec-filter-item">
      <span class="sec-filter-lab">{props.label}</span>
      {props.children}
    </div>
  );
}

function StatusChoice(props: { filter: SectionFilter }): JSX.Element {
  const f = () => props.filter;
  const value = () => {
    const st = f().status();
    return st ? LIFECYCLES.filter((s) => st.includes(s)).join(',') : '';
  };
  const combination = () => {
    const w = value();
    return w && !(LIFECYCLES as string[]).includes(w) ? w : '';
  };
  return (
    <select
      class="sec-filter-status"
      aria-label={text('filter.status')}
      disabled={f().loading()}
      title={f().loading() ? text('filter.loading') : undefined}
      value={value()}
      onChange={(e) => {
        const v = e.currentTarget.value;
        f().setStatus(v ? (v.split(',') as Lifecycle[]) : null);
      }}
    >
      <option value="">{text('filter.all')}</option>
      {LIFECYCLES.map((s) => (
        <option value={s}>{lifecyclePluralWord(s) as string}</option>
      ))}
      <Show when={combination()}>{(w) => (
        <option value={w()}>
          {w().split(',').map((s) => lifecyclePluralWord(s) as string).join(' + ')}
        </option>
      )}</Show>
    </select>
  );
}

export function FilterPanel(props: { filter: SectionFilter; pinned?: boolean }): JSX.Element {
  const f = () => props.filter;

  // Pinned: this panel hangs under a head that sticks, so its height is
  // part of the band a scroll target has to clear. A closed panel is
  // `hidden`, so it measures 0 by itself.
  let box: HTMLDivElement | undefined;
  onMount(() => {
    if (props.pinned && box) {
      onCleanup(publishHighest(box, '--sec-panel-h', document.documentElement));
    }
  });

  const onEscape = (e: KeyboardEvent) => {
    if (e.key !== 'Escape') return;
    if (closeDimMenu()) return;
    f().setOpen(false);
  };
  document.addEventListener('keydown', onEscape);
  onCleanup(() => document.removeEventListener('keydown', onEscape));

  return (
    <div
      ref={box}
      class={'sec-filter-panel' + (f().loading() ? ' is-loading' : '')}
      role="group"
      aria-label={text('filter.title')}
      hidden={!f().open()}
    >
      <Item label={text('filter.search')}>
        <input
          type="search"
          class="set-index-filter"
          placeholder={text('filter.placeholder')}
          aria-label={props.filter.id === 'section-requests'
            ? text('filter.ariaRequests') : text('filter.aria')}
          value={f().text()}
          onInput={(e) => f().setText(e.currentTarget.value)}
        />
      </Item>
      <Show when={f().offerOptions().length}>
        <Item label={text('filter.offer')}>
          <select
            class="sec-filter-offer"
            aria-label={text('filter.offerAria')}
            disabled={f().loading()}
            title={f().loading() ? text('filter.loading') : undefined}
            value={f().offerIri()}
            onChange={(e) => f().setOffer(e.currentTarget.value)}
          >
            <option value="">{text('filter.all')}</option>
            {f().offerOptions().map((o) => <option value={o.iri}>{o.title}</option>)}
          </select>
        </Item>
      </Show>
      <Show when={f().withStatus}>
        <Item label={text('filter.status')}><StatusChoice filter={props.filter} /></Item>
      </Show>
            <GroupingPath />
            <button
        type="button"
        class="sec-filter-clear"
        title={text('filter.clear')}
        aria-label={text('filter.clear')}
        disabled={f().loading()}
        hidden={!f().active()}
        onClick={() => f().clear()}
      >
        ×
      </button>
    </div>
  );
}
