import { Show } from 'solid-js';
import { stubOnlyContainers, t } from '../../model-boundary.js';
import { vocabularyName } from '../../model/default-corpus.js';
import {
  sources, compatIndex, endpoint, errors, loadNotice, loadStatus, listPhase, listError,
  model, engine, quadCount, scopeNotFound,
} from '../../stores/corpus.js';
import type { CorpusError, CorpusModel } from '../../stores/corpus.js';
import { notice, noticeVars, text, view } from '../../stores/view.js';
import { coveredNodes } from '../card/form-model.js';

export function statusText(
  m: CorpusModel,
  ctx: {
    sources: number; quads: number; errors: CorpusError[]; lang?: string;

    endpoint?: string | null;

    firstView?: boolean;

    compat?: boolean;

    scopeNotFound?: 'policy' | 'set' | null;

    covered?: number;
  },
): string {

  const tt = (k: string, v?: Record<string, unknown>) => t(k, v, ctx.lang);
  const c = m.counts;
  const terminated = stubOnlyContainers(m, 'agreement').length;
  const requests = (m.sets || []).filter((s) => s.isRequest).length;
  const setNote = tt('status.sets', { n: c.sets - requests }) + ', '
    + (requests ? tt('status.requests', { n: requests }) + ', ' : '');
  const vcNote = c.versionContainers
    ? tt('status.versionContainers', { n: c.versionContainers }) + ', ' : '';
  const errNote = ctx.errors.length ? tt('status.errors', { n: ctx.errors.length }) : '';

  const epNote = ctx.endpoint ? tt('status.sparqlNote', { ep: ctx.endpoint }) : '';

  const compatNote = (!ctx.firstView && ctx.compat) ? tt('status.compatIndex') : '';

  const scopeNote = ctx.scopeNotFound === 'policy' ? tt('status.policyNotFound')
    : (ctx.scopeNotFound === 'set' ? tt('status.setNotFound') : '');

  return tt('status.sources', { n: ctx.sources }) + ', '
    + tt('status.triples', { n: ctx.quads }) + ' · '
    + tt('status.offers', { n: c.offers }) + ', '
    + tt('status.agreements', { n: c.agreements + terminated }) + ', ' + setNote

    + vcNote + `${tt('status.artifacts', { n: c.artifacts + c.bundles })}`
    + (ctx.covered ? ', ' + tt('status.specified', { n: ctx.covered }) : '') + ' '
    + `${epNote}${scopeNote}`.trim()
    + errNote + compatNote
    + (ctx.firstView ? tt('status.firstView') : '');
}

export function StatusLine() {

  const ownSources = () => sources().filter((b) => !vocabularyName(b.url));
  const count = (m: CorpusModel) => statusText(m, {
    sources: ownSources().length, quads: quadCount(), errors: errors(),
    lang: view.lang,
    endpoint: endpoint(),
    firstView: listPhase() === 'first',
    compat: compatIndex(),
    scopeNotFound: scopeNotFound(),
    covered: coveredNodes(),
  });

  const errorLine = () => {
    const msg = errors().map((f) => f.message).join('; ');

    switch (listError()) {
      case 'fullIndex': return text('err.sparqlFullIndex', { msg });
      case 'endpoint': return text('err.sparql', { msg });
      default: return text('err.srcLoad', { msg });
    }
  };

  const line = () => {
    const m = model();

    const noticeKey = notice();
    if (noticeKey && loadStatus() !== 'loading' && loadStatus() !== 'error') {
      return text(noticeKey, noticeVars());
    }
    switch (loadStatus()) {

      case 'loading':
        return (m && listPhase() === 'first') ? count(m) : text(loadNotice(), {
          ep: endpoint() ?? '',
        });
      case 'error': return errorLine();
      case 'ready': return m ? count(m) : '';

      case 'empty': return text('status.empty');
      default: return '';
    }
  };
  return (
    <p
      class="app-status"
      id="app-status"
      role="status"
      aria-live="polite"
      aria-busy={loadStatus() === 'loading' ? 'true' : 'false'}
      data-engine={engine() ?? undefined}
    >
      <Show when={line()}>{(r) => <>{r()}</>}</Show>
    </p>
  );
}
